  bio String?

  /// User's role: guest, member, admin, or superAdmin. Required field.
  role String

  /// Whether the member account is currently banned.
  is_banned Boolean

  /// Reason for banning the member account.
  ban_reason String?

  /// Timestamp when the member account was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the member account was last updated.
  updated_at DateTime @db.Timestamptz

