/// JWT session tokens for member authentication with access and refresh
/// token support.
///
/// This table tracks active login sessions for member users, storing JWT
/// tokens and session metadata.
/// Sessions are created when members log in and invalidated when they log
/// out or change their password.
///
/// Sessions expire after 30 days of inactivity.
///
/// Relationships:
/// - Belongs to: discussion_board_members (member)
/// - Session management: Handles login/logout and password change invalidation
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_member_sessions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belonged member's {@link discussion_board_members.id}.
  discussion_board_member_id String @db.Uuid

  /// JWT access token for authentication. Short-lived token (15 minutes) used
  /// for API requests.
  access_token String

  /// JWT refresh token for session continuation. Long-lived token (30 days)
  /// used to obtain new access tokens.
  refresh_token String

  /// IP address of the client when the session was created.
  ip String

  /// Referrer header value when the session was created.
  referrer String?

  /// User agent string from the client browser.
  user_agent String?

  /// Timestamp when the session was created. Also serves as last activity
  /// timestamp.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the session expires (30 days from created_at). Session
  /// becomes invalid after this time.
  expired_at DateTime @db.Timestamptz

  /// Timestamp when the session was explicitly invalidated (logout or password
  /// change). Null if session is still valid.
  invalidated_at DateTime? @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  // spellchecker: ignore-next-line
  member discussion_board_members @relation(fields: [discussion_board_member_id], references: [id], onDelete: Cascade, map: "discussion_board_member_sessions_discussion_board_memb_974b09f5")

  //----
  // INDEXES
  //----
  // spellchecker: ignore-next-line
  @@index([discussion_board_member_id, created_at], map: "discussion_board_member_sessions_discussion_board_memb_336fc309")
  @@index([expired_at])
  @@index([invalidated_at])
}

/// Password reset tokens for member account recovery with expiration. Tracks
/// reset requests, validates tokens, and records when resets are completed.
/// Provides security audit trail for password change operations.
///
/// ## Business Purpose
/// - Enables secure password recovery for member accounts
/// - Validates reset tokens with expiration checking
/// - Records when password resets are completed
/// - Maintains audit trail for security compliance
///
/// ## Key Relationships
/// - Belongs to discussion_board_members (member account)
/// - One member can have multiple password resets over time
/// - Used for recovery workflows, not日常 authentication
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_member_password_resets {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Member's {@link discussion_board_members.id} being reset.
  discussion_board_member_id String @db.Uuid

  /// Unique password reset token for authentication. Used to verify password
  /// reset requests securely.
  token String

  /// Expiration time for the password reset token. Tokens must be used before
  /// this time to be valid.
  expires_at DateTime @db.Timestamptz

  /// Timestamp when the password was successfully reset using this token. Null
  /// until reset is completed.
  used_at DateTime? @db.Timestamptz

  /// IP address where the password reset request was initiated.
  ip String

  /// Full URL where the password reset request originated.
  href String

  /// Referrer header from the password reset request.
  referrer String

  /// When the password reset request was created.
  created_at DateTime @db.Timestamptz

  /// When the password reset record was last updated.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp for password reset records.
  deleted_at DateTime? @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  // spellchecker: ignore-next-line
  member discussion_board_members @relation(fields: [discussion_board_member_id], references: [id], onDelete: Cascade, map: "discussion_board_member_password_resets_discussion_boa_2263beb8")

  //----
  // INDEXES
  //----
  @@unique([token])
  // spellchecker: ignore-next-line
  @@index([discussion_board_member_id, created_at], map: "discussion_board_member_password_resets_discussion_boa_8cc0ab58")
  @@index([expires_at])
}

