/// Password reset tokens for super admin account recovery with expiration.
///
/// This table stores secure password reset tokens for super administrators
/// who need to recover their account access. Each token is tied to a
/// specific super admin and has a defined expiration time for security
/// purposes.
///
/// ## Usage
/// - Super administrators can request password resets when they forget their
/// credentials
/// - Tokens are generated with cryptographically secure random values
/// - Tokens expire after a defined period (typically 1 hour)
/// - Once used, tokens are invalidated to prevent reuse
///
/// ## Security Considerations
/// - Tokens should be single-use and invalidated immediately after
/// successful password reset
/// - Token generation should use cryptographically secure random values
/// - Expired tokens should be automatically cleaned up
/// - Multiple concurrent reset requests may be allowed but old tokens should
/// be invalidated
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_super_admin_password_resets {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Super admin account requesting password reset. {@link
  /// discussion_board_super_admins.id}.
  super_admin_id String @db.Uuid

  /// Secure password reset token generated for authentication.
  token String

  /// Token expiration timestamp. Tokens are valid until this time.
  expires_at DateTime @db.Timestamptz

  /// When this password reset record was created.
  created_at DateTime @db.Timestamptz

  /// When this password reset record was last updated.
  updated_at DateTime @db.Timestamptz

  /// When this password reset record was deleted (soft delete). Null if active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  // spellchecker: ignore-next-line
  superAdmin discussion_board_super_admins @relation(fields: [super_admin_id], references: [id], onDelete: Cascade, map: "discussion_board_super_admin_password_resets_super_adm_6159c89d")

  //----
  // INDEXES
  //----
  @@unique([token])
  // spellchecker: ignore-next-line
  @@unique([super_admin_id, token], map: "discussion_board_super_admin_password_resets_super_adm_e19217cf")
  // spellchecker: ignore-next-line
  @@index([super_admin_id, created_at], map: "discussion_board_super_admin_password_resets_super_adm_0473f316")
  @@index([expires_at])
}

