    );
  }
  // 4. Test search with no results using unique term
  const noResultOutput = await api.functional.discussionBoard.sections.index(
    connection,
    {
      body: {
        search: "NonExistentTerm12345XYZ",
      } satisfies IDiscussionBoardSection.IRequest,
    },
