    await api.functional.discussionBoard.member.sections.articles.create(
      memberBConnection,
      {
        sectionId: sectionId,
        body: {
          title: RandomGenerator.paragraph({ sentences: 1 }),
          content: RandomGenerator.content({
            paragraphs: 3,
            sentenceMin: 5,
            sentenceMax: 10,
          }),
        } satisfies IDiscussionBoardArticle.ICreate,
      },
