  TestValidator.predicate(
    "first page records > 0",
    firstPage.pagination.records > 0,
  );
  TestValidator.predicate(
    "first page pages > 0",
    firstPage.pagination.pages > 0,
  );
  // 5. Verify data structure
  TestValidator.equals("first page data length", firstPage.data.length, 2);
