  const records = hasMore ? total : transformed.length;
  return {
    data: paginatedData,
    pagination: {
      current: page,
      limit: limit,
      records: records,
      pages: Math.ceil(records / limit),
    } satisfies IPage.IPagination,
  } satisfies IPageIDiscussionBoardAdministratorRequest.ISummary;
}

